#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9

banner "MediaSafe — provision the accounts, secrets and Neon branches (#37)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight — the values that need no dashboard"
say "Three values can be settled right here, before any browser opens."
say ""
say "Local development runs against Docker Postgres, NOT Neon. Neon's two"
say "connection strings are for Vercel, and you collect them in stages 3 and 4."
say ""

command -v gh >/dev/null 2>&1 || warn "the gh CLI isn't installed — not required here, but handy later"
# In a git worktree .git is a file, not a directory, so test the toplevel instead.
[[ "$(git rev-parse --show-toplevel 2>/dev/null)" == "$PWD" ]] \
  || warn "this doesn't look like a repo root — run the wizard from there"

# Keep any secret already in .env. Regenerating it would invalidate every live
# session, and the banner promises a re-run keeps what is already saved.
AUTH_SECRET=$(_existing BETTER_AUTH_SECRET || true)
if [[ -n "$AUTH_SECRET" ]]; then
  say "Keeping the Better Auth secret already in $ENV_FILE."
  note "Rotating it would sign out every existing session."
elif command -v openssl >/dev/null 2>&1; then
  AUTH_SECRET=$(openssl rand -base64 32)
  say "Generated a Better Auth secret with openssl."
else
  warn "openssl not found — paste a random 32-byte secret instead"
  ask_secret AUTH_SECRET "Random secret (32+ bytes):"
fi
write_env BETTER_AUTH_SECRET "$AUTH_SECRET"
write_env BETTER_AUTH_URL "http://localhost:3000"
write_env DATABASE_URL "postgres://mediasafe:mediasafe@localhost:5432/mediasafe"
note "DATABASE_URL points at Docker Postgres. 'npm run db:up' brings that container up."
write_env DATABASE_WS_PROXY "localhost:5433"
note "DATABASE_WS_PROXY is the local WebSocket proxy that fronts Docker Postgres."
note "Leave it OUT of Vercel — Neon speaks WebSocket itself, and setting it there"
note "would route production through a proxy that does not exist."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Vercel — the project"
say "One Next.js app on Vercel Hobby. One deploy target, one git push."
say "This goes first because Google's redirect URIs in stage 6 need the domain"
say "Vercel hands you here."
open_url "https://vercel.com/new"
step "Import the MediaSafe repository."
step "Framework preset: Next.js. Leave the build settings alone — ticket #39"
step "  changes the build command so migrations run as its first half."
step "Do NOT add Neon from Vercel's marketplace integration. Decision #2 was to"
step "  sign up to Neon direct, and the integration provisions a branch per PR,"
step "  which #18 replaced with one shared schema-only branch."
step "Deploy. It will fail — there is no application code yet. Expected."
say ""
step "Open Settings → Domains and copy the production domain."
ask VERCEL_PRODUCTION_URL "Production URL (e.g. https://mediasafe.vercel.app):"
write_env VERCEL_PRODUCTION_URL "$VERCEL_PRODUCTION_URL"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Neon — the project and its production branch"
say "Postgres on Neon Free, signed up direct. Free gives 3 root branches and"
say "0.5 GB shared across them — ample for 472 titles and ~18,715 watches."
open_url "https://console.neon.tech/app/projects"
step "Create a project. Pick the region closest to your Vercel region."
step "Postgres version: take the current default."
say ""
step "Open the project's Connect panel and choose the POOLED connection string."
step "  The pooled host has '-pooler' in it."
warn "Pooled matters. The app and the migration runner both use the WebSocket"
warn "Pool from neon-serverless, because Neon's HTTP interface has no"
warn "interactive transactions and halt-on-partial-failure needs one."
ask_secret NEON_PRODUCTION_URL "Paste the POOLED production connection string:"
write_env NEON_PRODUCTION_URL "$NEON_PRODUCTION_URL"
note "This belongs in Vercel's Production scope — never in the local DATABASE_URL."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Neon — the shared schema-only preview branch"
say "Every preview deployment shares ONE branch, and it holds zero rows of"
say "anybody's data. A schema-only branch copies the structure and leaves all"
say "row data behind — so no delete statement has to stay correct for other"
say "people's watch history to be absent. The guarantee is structural."
open_url "https://console.neon.tech/app/projects"
step "Select your project, then Branches."
step "Click 'New branch'."
step "Parent branch: your production branch."
step "Name it something obvious — 'preview-shared' does the job."
step "Select the 'Schema only' option."
warn "Leave 'Automatically delete branch after' OFF for this one. The 30-day"
warn "expiry rule covers every OTHER non-production branch; this shared branch"
warn "is the stated exception."
step "Click Create."
say ""
step "Open the new branch's connection details and copy its POOLED string."
ask_secret NEON_PREVIEW_URL "Paste the POOLED schema-only branch string:"
write_env NEON_PREVIEW_URL "$NEON_PREVIEW_URL"
say ""
if confirm "Does the console show this branch as schema-only, with no rows?"; then
  say "Good — that is the property the whole decision rests on."
else
  SKIPPED+=("VERIFY the preview branch is schema-only and holds zero rows")
  warn "recorded as still-to-verify"
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Neon — the 30-day expiry rule for every other branch"
say "Neon's own cleanup runs only when a preview deployment is next created, so"
say "an untouched branch can live indefinitely. Hence a hard expiry."
say ""

EXPIRY=""
if date -u -v+30d +%Y-%m-%dT%H:%M:%SZ >/dev/null 2>&1; then
  EXPIRY=$(date -u -v+30d +%Y-%m-%dT%H:%M:%SZ)
elif date -u -d '+30 days' +%Y-%m-%dT%H:%M:%SZ >/dev/null 2>&1; then
  EXPIRY=$(date -u -d '+30 days' +%Y-%m-%dT%H:%M:%SZ)
fi

if [[ -n "$EXPIRY" ]]; then
  say "30 days from now, in the RFC 3339 format Neon wants:"
  printf '\n      %s%s%s\n\n' "$BOLD" "$EXPIRY" "$RESET"
fi
warn "The dashboard presets stop at 7 days (1 hour, 1 day, 7 days). 30 days needs"
warn "a custom date — available when UPDATING an existing branch, not when"
warn "creating one — or --expires-at on the CLI."
note "30 days is also Neon's ceiling: it rejects a timestamp more than 30 days out."
say ""
say "The CLI form, for whenever a throwaway branch appears:"
printf '\n      %sneon branches create --expires-at %s%s\n' "$DIM" "${EXPIRY:-<RFC3339>}" "$RESET"
printf '      %sneon branches set-expiration <branch> --expires-at %s%s\n\n' "$DIM" "${EXPIRY:-<RFC3339>}" "$RESET"
note "Right now there is probably nothing to apply this to — previews all share"
note "the stage 4 branch, and that one is exempt. This stage exists so the rule"
note "reaches you before the first throwaway branch does."
if confirm "Does any non-production branch besides the shared one exist now?"; then
  SKIPPED+=("Set a 30-day expiry on the other non-production Neon branch(es)")
  warn "recorded — set its expiry before moving on"
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Google — the OAuth client"
say "Google is the ONLY sign-in method. No password, no magic link, and no"
say "email field anywhere in the system."
open_url "https://console.cloud.google.com/projectcreate"
step "Create a Google Cloud project called MediaSafe. A NEW one — even if you"
step "  already have projects sitting there."
warn "Do not reuse another app's project or OAuth client. The consent screen"
warn "takes its name from the project's App name, so everyone signing in to"
warn "MediaSafe is asked to grant access to whatever that project is called."
warn "Google also records consent against the client id, so MediaSafe would"
warn "silently inherit everyone who ever authorised the other app — and the"
warn "day that project is deleted, sign-in stops."
note "This is not hypothetical: the first run of this wizard reused a retired"
note "project's client, and MediaSafe's consent screen read \"Accountability\"."
say ""
step "Open the consent screen: Google Auth Platform → Branding on the current"
step "  console, APIs & Services → OAuth consent screen on the older one."
step "App name: MediaSafe. Put your own address in as the support and developer"
step "  contact. Leaving it in Testing mode is fine — with about three users"
step "  you never reach the verification threshold."
step "While it is in Testing, add yourself under Audience → Test users, or"
step "  Google refuses the sign-in it otherwise completes."
step "Scopes: the defaults (email, profile, openid). Nothing else is needed."
say ""
step "Then Clients → Create client (older console: Credentials → Create"
step "  credentials → OAuth client ID). Application type: Web application."
say ""
say "Authorised redirect URIs — add these two, exactly:"
printf '\n      %shttp://localhost:3000/api/auth/callback/google%s\n' "$BOLD" "$RESET"
printf '      %s%s/api/auth/callback/google%s\n\n' "$BOLD" "${VERCEL_PRODUCTION_URL:-<your-production-url>}" "$RESET"
warn "Preview deployments get a unique URL each time and Google accepts only"
warn "exact URIs — so sign-in will NOT work on a preview until #39 gives"
warn "previews a stable alias. A known gap, not something you did wrong."
say ""
ask GOOGLE_CLIENT_ID "Paste the Client ID:"
ask_secret GOOGLE_CLIENT_SECRET "Paste the Client secret:"
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
say ""
# The one thing in this stage a wizard can actually check, and it is the one
# that went wrong: nothing in the client id says which project it came from, so
# the only way to know is to read the screen a stranger would read.
if ! confirm "Does the consent screen say \"Sign in to MediaSafe\"?"; then
  warn "Then this client belongs to another project. Change App name to"
  warn "MediaSafe under Branding, or — better — go back and make MediaSafe its"
  warn "own project and paste that client instead."
  warn "Leaving it is not cosmetic: the name people are asked to trust at the"
  warn "one moment they hand over their Google account is the wrong one."
  SKIPPED+=("Google consent screen does not say MediaSafe — see stage 6")
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Sentry — the project"
say "Sentry is the error record, and its event id is the only technical string"
say "a user ever sees: the reference id on a failure toast IS this id, not a"
say "second identifier someone has to correlate with it."
open_url "https://sentry.io/organizations/new/"
step "Create an organisation if you have none, then a new project."
step "Platform: Next.js. Name it MediaSafe."
step "The Developer plan is free and ample for three users."
say ""
step "Copy the DSN (Settings → Projects → your project → Client Keys)."
ask SENTRY_DSN "Paste the DSN:"
write_env SENTRY_DSN "$SENTRY_DSN"
write_env NEXT_PUBLIC_SENTRY_DSN "$SENTRY_DSN"
say ""
step "Read your organisation and project slugs out of the URL bar."
ask SENTRY_ORG "Organisation slug:"
ask SENTRY_PROJECT "Project slug:"
write_env SENTRY_ORG "$SENTRY_ORG"
write_env SENTRY_PROJECT "$SENTRY_PROJECT"
say ""
step "Settings → Auth Tokens → Create token, with the project:releases scope."
note "This uploads source maps at build time, so a stack trace is readable."
ask_secret SENTRY_AUTH_TOKEN "Paste the auth token:"
write_env SENTRY_AUTH_TOKEN "$SENTRY_AUTH_TOKEN"
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "TMDB — the API Read Access Token"
say "TMDB is the single metadata source for every film, show, episode, air date"
say "and poster in the product. Without this credential the catalogue cannot be"
say "searched and nothing can be added to a library at all."
open_url "https://www.themoviedb.org/settings/api"
step "Sign in, or create a TMDB account."
step "If you have no API access yet, request it. It is free, and a personal"
step "  project is an accepted use — you will be asked for an application name"
step "  and a URL. Your repository URL is a fine answer."
say ""
step "On the API settings page, find 'API Read Access Token'."
warn "Take the READ ACCESS TOKEN, not the older 'API Key'. The token is a bearer"
warn "credential that works across TMDB's v3 and v4 APIs, so it is the one"
warn "credential rather than two. It is long, and it starts with 'eyJ'."
ask_secret TMDB_READ_ACCESS_TOKEN "Paste the API Read Access Token:"
write_env TMDB_READ_ACCESS_TOKEN "$TMDB_READ_ACCESS_TOKEN"
note "Server-side only. It is deliberately NOT a NEXT_PUBLIC_ variable — it is a"
note "bearer token, and bundling it would serve it to every visitor."
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Land it — .env.example, the secret check, and Vercel's scopes"
say "Writing a committed example file that names every variable and carries no"
say "real value."

cat > .env.example <<'EXAMPLE_EOF'
# MediaSafe — environment variables.
# Copy to .env and fill in, or run scripts/provision.sh, which writes it for you.
# Never commit .env.

# Local development runs against Docker Postgres, not Neon. `npm run db:up` brings
# up both containers; docs/local-development.md explains why there are two.
DATABASE_URL=postgres://mediasafe:mediasafe@localhost:5432/mediasafe

# The local WebSocket proxy that fronts Docker Postgres, so the one driver
# (neon-serverless over a WebSocket Pool) works locally too. LEAVE THIS UNSET in
# Vercel: Neon speaks WebSocket itself, and setting it there would route production
# through a proxy that does not exist.
DATABASE_WS_PROXY=localhost:5433

# Better Auth. Google is the only sign-in method.
BETTER_AUTH_SECRET=
BETTER_AUTH_URL=http://localhost:3000
GOOGLE_CLIENT_ID=
GOOGLE_CLIENT_SECRET=

# Sentry. The event id is the reference id a user reads back to you.
SENTRY_DSN=
NEXT_PUBLIC_SENTRY_DSN=
SENTRY_ORG=
SENTRY_PROJECT=
SENTRY_AUTH_TOKEN=

# TMDB, the single metadata source. A bearer token, sent as an Authorization
# header, valid across TMDB's v3 and v4 APIs. Server-side only — never
# NEXT_PUBLIC_, or it would be bundled and served to every visitor.
TMDB_READ_ACCESS_TOKEN=

# Neon. Not used by the app locally — the app reads DATABASE_URL. These two are
# recorded here so provisioning has one home, and are copied into Vercel:
#   NEON_PRODUCTION_URL -> Vercel Production scope, as DATABASE_URL
#   NEON_PREVIEW_URL    -> Vercel Preview scope, as DATABASE_URL (schema-only)
# Both must be the POOLED connection string — the host with '-pooler' in it.
NEON_PRODUCTION_URL=
NEON_PREVIEW_URL=

# The domain Vercel assigns. Google's redirect URIs are built from it.
VERCEL_PRODUCTION_URL=
EXAMPLE_EOF
printf '  %s✓ wrote%s .env.example\n' "$GREEN" "$RESET"

say ""
say "Checking that nothing secret is committed."
if [[ -f .gitignore ]] && grep -qE '^\.env' .gitignore; then
  printf '  %s✓%s .env is gitignored\n' "$GREEN" "$RESET"
else
  printf '.env\n.env.local\n' >> .gitignore
  printf '  %s✓ added%s .env to .gitignore\n' "$GREEN" "$RESET"
fi
if git ls-files --error-unmatch .env >/dev/null 2>&1; then
  warn ".env IS TRACKED BY GIT — remove it with: git rm --cached .env"
  SKIPPED+=("URGENT: .env is tracked by git — run: git rm --cached .env")
else
  printf '  %s✓%s .env is not tracked by git\n' "$GREEN" "$RESET"
fi

say ""
say "Last job, by hand — Vercel → Settings → Environment Variables."
say "Scope is what matters here; getting it wrong points production at an"
say "empty database."
printf '\n'
printf '  %s%-24s %-28s %s%s\n' "$BOLD" "VARIABLE" "VALUE" "SCOPE" "$RESET"
printf '  %-24s %-28s %s\n' "DATABASE_URL" "your NEON_PRODUCTION_URL" "Production only"
printf '  %-24s %-28s %s\n' "DATABASE_URL" "your NEON_PREVIEW_URL" "Preview only"
printf '  %-24s %-28s %s\n' "BETTER_AUTH_SECRET" "same as .env" "All"
printf '  %-24s %-28s %s\n' "BETTER_AUTH_URL" "your production URL" "Production"
printf '  %-24s %-28s %s\n' "GOOGLE_CLIENT_ID" "same as .env" "All"
printf '  %-24s %-28s %s\n' "GOOGLE_CLIENT_SECRET" "same as .env" "All"
printf '  %-24s %-28s %s\n' "SENTRY_DSN" "same as .env" "All"
printf '  %-24s %-28s %s\n' "NEXT_PUBLIC_SENTRY_DSN" "same as .env" "All"
printf '  %-24s %-28s %s\n' "SENTRY_AUTH_TOKEN" "same as .env" "All"
printf '  %-24s %-28s %s\n' "SENTRY_ORG" "same as .env" "All"
printf '  %-24s %-28s %s\n' "SENTRY_PROJECT" "same as .env" "All"
printf '  %-24s %-28s %s\n' "TMDB_READ_ACCESS_TOKEN" "same as .env" "All"
printf '\n'
note "Both DATABASE_URL rows are deliberate: one variable, two scopes, two"
note "different databases. Production carries the real library; Preview carries"
note "the schema-only branch with zero rows."
note "SENTRY_ORG and SENTRY_PROJECT are belt-and-braces: withSentryConfig usually"
note "takes org and project as literals in next.config.ts and reads only the auth"
note "token from the environment. Setting them costs nothing and means a build"
note "that expects them in the environment still uploads its source maps."
warn "BETTER_AUTH_URL is Production-scoped here because a preview's URL is not"
warn "known ahead of time. Preview sign-in is already blocked for that reason"
warn "until #39 lands a stable alias — set it to that alias when it does."
SKIPPED+=("Set the 12 Vercel environment variables above, at the scopes shown")
say ""

# The £5/month ceiling is meant to stay unspent — worth one look, not an assumption.
say "One last look, since '£0 spent' is an acceptance criterion and not a hope:"
step "Vercel → Settings → Billing shows the Hobby plan."
step "Neon → Billing shows the Free plan."
step "Sentry → Settings → Subscription shows the Developer plan."
if confirm "Are all three on their free tier, with £0 recurring?"; then
  say "Good — the £5/month ceiling stays an escape hatch rather than a bill."
else
  SKIPPED+=("VERIFY every service is on its free tier — something is billing you")
  warn "recorded — find the paid one before it renews"
fi
pause "Press Enter for the summary"

finish
